package com.eatwhat.service;
import com.eatwhat.dto.AssistantV4Contract.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class AssistantRequirementResolverTest {
 ActionProposal proposal(String text){ActionProposal p=new ActionProposal();ActionIntent a=new ActionIntent();a.setKind("draft_update");a.setArguments(AssistantV4ContextService.map("operation","adjust","contextPatch",AssistantV4ContextService.map("requirements",text)));p.getSteps().add(a);return p;}
 @Test void explicit_exclusion_becomes_current_meal_filter_without_mutating_original(){ActionProposal p=proposal("这餐不吃香菜");AssistantRequirementResolver.RequirementDecision d=new AssistantRequirementResolver().resolve(new ModelContext(),p);assertEquals("applicable",d.getStatus());Map<?,?> patch=(Map<?,?>)d.getValidatedProposal().getSteps().get(0).getArguments().get("contextPatch");assertFalse(patch.containsKey("requirements"));assertEquals(Collections.singletonList("香菜"),((Map<?,?>)patch.get("criteria")).get("excludedIngredients"));assertTrue(((Map<?,?>)p.getSteps().get(0).getArguments().get("contextPatch")).containsKey("requirements"));}
 @Test void existing_exclusions_are_retained(){ModelContext c=new ModelContext();c.getConstraints().put("hard",AssistantV4ContextService.map("excludedIngredients",Collections.singletonList("花生")));Map<?,?> patch=(Map<?,?>)new AssistantRequirementResolver().resolve(c,proposal("不吃香菜")).getValidatedProposal().getSteps().get(0).getArguments().get("contextPatch");assertEquals(Arrays.asList("花生","香菜"),((Map<?,?>)patch.get("criteria")).get("excludedIngredients"));}
 @Test void vague_or_unsupported_words_are_not_claimed_applied(){for(String text:Arrays.asList("简单一点","少油","清淡点","不吃辣或者吃一点","永久不要香菜"))assertEquals("needs_input",new AssistantRequirementResolver().resolve(new ModelContext(),proposal(text)).getStatus());}
 @Test void explicit_max_minutes_uses_existing_structured_field(){AssistantRequirementResolver.RequirementDecision d=new AssistantRequirementResolver().resolve(new ModelContext(),proposal("每道菜最多20分钟"));Map<?,?> patch=(Map<?,?>)d.getValidatedProposal().getSteps().get(0).getArguments().get("contextPatch");assertEquals(20,((Map<?,?>)patch.get("criteria")).get("maxCookMinutes"));}
 @Test void explicit_choice_can_resolve_target_but_does_not_invent_one(){ModelContext c=new ModelContext();c.getRequestContext().put("clarification",AssistantV4ContextService.map("selection",AssistantV4ContextService.map("dishId",2L)));ActionProposal p=new ActionProposal();ActionIntent action=new ActionIntent();action.setKind("draft_update");action.setArguments(AssistantV4ContextService.map("operation","adjust","targetConstraints",AssistantV4ContextService.map("excludedIngredients",Collections.singletonList("香菜"))));p.getSteps().add(action);assertEquals(2L,new AssistantRequirementResolver().resolve(c,p).getValidatedProposal().getSteps().get(0).getArguments().get("targetDishId"));}
 @Test void plain_structured_actions_remain_unchanged(){ActionProposal p=proposal("少油");((Map<?,?>)p.getSteps().get(0).getArguments().get("contextPatch")).clear();assertEquals("applicable",new AssistantRequirementResolver().resolve(new ModelContext(),p).getStatus());}
}
